export const TEAMS=[{id:'sales',name:'Commercial',metric:'Margin',actions:['Bespoke deals','Standard deals','Decline complexity'],out:[{delivery:-8,support:-5},{},{delivery:4,support:3}],buffer:[1.15,1,.7]},{id:'delivery',name:'Delivery',metric:'Release speed',actions:['Fast releases','Paced releases','Stabilise first'],out:[{platform:-7,support:-5},{},{platform:6,support:4}],buffer:[1.25,1,.65]},{id:'platform',name:'Platform',metric:'Availability',actions:['Maximum reserve','Balanced reserve','Lean reserve'],out:[{sales:-6,delivery:-2},{},{sales:7,delivery:2}],buffer:[.45,1,1.6]},{id:'support',name:'Support',metric:'Low handling effort',actions:['Strict deflection','Triage','Deep support'],out:[{sales:-7,platform:-3},{},{sales:7,platform:3}],buffer:[1.3,1,.5]}];
export const STYLES=['Protect own metric','Balance the work','Absorb / release work'];
export function create(){return {actions:{sales:0,delivery:0,platform:0,support:0},pressure:1,reward:0,weights:{sales:1,delivery:1,platform:1,support:1}};}
export function validate(s){for(const team of TEAMS){if(![0,1,2].includes(s.actions?.[team.id]))throw Error('Choose one of the three actions.');if(!Number.isFinite(s.weights?.[team.id])||s.weights[team.id]<.5||s.weights[team.id]>3)throw Error('Outcome weights must be 0.5–3.');}if(!Number.isFinite(s.pressure)||s.pressure<0||s.pressure>2||!Number.isFinite(s.reward)||s.reward<0||s.reward>1)throw Error('Invalid coupling or reward share.');return s;}
export function evaluate(s){validate(s);const outcomes=Object.fromEntries(TEAMS.map(t=>[t.id,50+[9,4,-2][s.actions[t.id]]])),flows=[];for(const from of TEAMS)for(const [to,raw] of Object.entries(from.out[s.actions[from.id]])){const receiver=TEAMS.find(t=>t.id===to),value=raw*s.pressure*(raw<0?receiver.buffer[s.actions[to]]:1);outcomes[to]+=value;flows.push({from:from.id,to,value,raw});}const global=TEAMS.reduce((sum,t)=>sum+outcomes[t.id]*s.weights[t.id],0)/TEAMS.reduce((sum,t)=>sum+s.weights[t.id],0);const rewards=Object.fromEntries(TEAMS.map(t=>[t.id,(1-s.reward)*outcomes[t.id]+s.reward*global]));return {outcomes,flows,global,rewards};}
export function assign(s,id,action){if(!TEAMS.some(t=>t.id===id))throw Error('Unknown team.');const next=structuredClone(s);next.actions[id]=action;return validate(next);}
export function bestResponse(s,id){let best=s.actions[id],score=evaluate(s).rewards[id];for(let action=0;action<3;action++){const trial=assign(s,id,action),value=evaluate(trial).rewards[id];if(value>score+1e-9){score=value;best=action;}}return best;}
export function respond(s){return {...structuredClone(s),actions:Object.fromEntries(TEAMS.map(t=>[t.id,bestResponse(s,t.id)]))};}
export function run(s,maxSteps=20){let current=structuredClone(s);const history=[current],seen=new Set([JSON.stringify(current.actions)]);for(let i=0;i<maxSteps;i++){const next=respond(current);if(JSON.stringify(next.actions)===JSON.stringify(current.actions))return {state:current,history,status:'stable'};history.push(next);const key=JSON.stringify(next.actions);if(seen.has(key))return {state:next,history,status:'cycle'};seen.add(key);current=next;}return {state:current,history,status:'limit'};}
export function policyComparison(s){return [0,1].map(reward=>{const start={...structuredClone(s),reward,actions:Object.fromEntries(TEAMS.map(t=>[t.id,1]))};const result=run(start);return {reward,...result,result:evaluate(result.state)};});}
